import std.collection.*

func processEntry(q: ArrayDeque<Int64>, t: Int64): Int64 {
if (q.isEmpty()) {return -81}
q.size-t
}

main() {
let c0 = ArrayDeque<Int64>()
c0.addLast(4)
c0.addLast(-2)
c0.addLast(7)
let r0=processEntry(c0, 1)
println(r0 == 3 && c0.toArray() == [4, -2, 7])
let c1 = ArrayDeque<Int64>()
c1.addLast(1)
c1.addLast(6)
let r1=processEntry(c1, 2)
println(r1 == -1 && c1.toArray() == [1, 6])
}

